function validate([file, queries]) {
  if (typeof file !== 'string' || file.length < 1 || file.length > 500) return 'file needs 1 to 500 characters.';
  if (!/^[A-Za-z0-9]+$/.test(file)) return 'file uses only English letters and digits.';
  if (queries.length < 1 || queries.length > 10) return 'queries needs 1 to 10 values.';
  if (queries.some(n => !Number.isInteger(n) || n < 1 || n > 500)) return 'Each query is a whole number from 1 to 500.';
  return null;
}

