function read(read4) {
  const buf4 = new Array(4);
  let start = 0;
  let end = 0;

  return function reader(buf, n) {
    let copied = 0;
    while (copied < n) {
      if (start === end) {
        end = read4(buf4);
        start = 0;
        if (end === 0) {
          break;
        }
      }
      buf[copied] = buf4[start];
      copied++;
      start++;
    }
    return copied;
  };
}

