function read(read4) {
  const pending = [];
  let finished = false;
  return (buf, n) => {
    while (!finished && pending.length < n) {
      const chunk = [];
      const got = read4(chunk);
      if (got === 0) finished = true;
      for (let k = 0; k < got; k++) pending.push(chunk[k]);
    }
    const taken = pending.splice(0, Math.min(n, pending.length));
    taken.forEach((c, k) => { buf[k] = c; });
    return taken.length;
  };
}

