function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = rand() < 0.5 ? 'abc' : 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const length = size === 'large' ? 500 : 1 + pick(14);
  let file = '';
  for (let i = 0; i < length; i++) file += alphabet[pick(alphabet.length)];
  const count = size === 'large' ? 10 : 1 + pick(6);
  const queries = [];
  for (let i = 0; i < count; i++) {
    const roll = rand();
    if (size === 'large') queries.push(roll < 0.1 ? 500 : 1 + pick(120));
    else queries.push(roll < 0.1 ? 1 + pick(500) : 1 + pick(7));
  }
  return [file, queries];
}
